class Product {
  // Cached average — updated when reviews change
  private double averageRating;
  private int reviewCount;

  void updateRating(double newRating) {
    averageRating = (averageRating * reviewCount + newRating)
                   / (reviewCount + 1);
    reviewCount++;
  }
}

