public enum OrderStatus {
  PLACED, CONFIRMED, PROCESSING, SHIPPED, DELIVERED, CANCELLED, RETURNED;
}

public class Order {
  private OrderStatus status = OrderStatus.PLACED;

  public void confirm() {
    if (status != OrderStatus.PLACED)
      throw new InvalidStateException("Cannot confirm " + status);
    this.status = OrderStatus.CONFIRMED;
    // notify warehouse
  }

  public void cancel() {
    if (!EnumSet.of(PLACED, CONFIRMED).contains(status))
      throw new InvalidStateException("Cannot cancel " + status);
    this.status = OrderStatus.CANCELLED;
    // process refund
  }
}

