class Order {
    OrderStatus status;
    void cancel() {
        if (status == OrderStatus.SHIPPED || status == OrderStatus.DELIVERED)
            throw new IllegalStateException("too late");
        // every method re-checks status; easy to miss a case and allow a bad jump
        status = OrderStatus.CANCELLED;
    }
}
```

```java
interface OrderState {
    OrderState ship();
    OrderState cancel();
    OrderState deliver();
}
class PlacedState implements OrderState {
    public OrderState ship()    { return new ShippedState(); }
    public OrderState cancel()  { return new CancelledState(); }   // allowed here
    public OrderState deliver() { throw new IllegalStateException("ship first"); }
}
class ShippedState implements OrderState {
    public OrderState ship()    { throw new IllegalStateException("already shipped"); }
    public OrderState cancel()  { throw new IllegalStateException("cannot cancel shipped"); }
    public OrderState deliver() { return new DeliveredState(); }
}
// Order.cancel() = state = state.cancel();  -- invalid jumps simply can't happen
