interface PaymentProcessor {
    PaymentResult initiate(Payment payment);
    PaymentResult verify(String externalTxnId);
    PaymentResult refund(Payment payment);
}

class UpiProcessor implements PaymentProcessor {
    public PaymentResult initiate(Payment p) { /* call UPI gateway */ return PaymentResult.pending(); }
    public PaymentResult verify(String id)   { /* poll gateway */     return PaymentResult.success(); }
    public PaymentResult refund(Payment p)   { return PaymentResult.refunded(); }
}

class PaymentService {
    private final Map<PaymentMethod, PaymentProcessor> processors;
    PaymentResult pay(Order order, PaymentMethod method, String idempotencyKey) {
        // idempotency: same key -> return the existing result, never double-charge
        if (repo.exists(idempotencyKey)) return repo.resultFor(idempotencyKey);
        Payment payment = repo.create(order, method, idempotencyKey);
        return processors.get(method).initiate(payment);
    }
}
```
*The idempotency key makes a retried request safe — the customer is charged at most once.*
